/**
 * Startup env validation. No Joi/zod dependency: this environment's
 * `package-lock.json` doesn't exist yet (see
 * CHANGES-lockfile-and-ci-hardening-2026-09-28.md) and nothing here could
 * install a new package to confirm it resolves, so this stays a plain
 * function `@nestjs/config`'s `ConfigModule.forRoot({ validate })` already
 * supports directly — no new dependency to add to a lockfile that isn't
 * being generated by this same change.
 *
 * Before this, `JwtStrategy`, `AuthService`, `PrismaService` and
 * `RedisModule` each read their own env vars straight off `ConfigService`
 * with no check that they were ever set. A blank `JWT_ACCESS_SECRET`
 * booted the server fine and only surfaced once someone tried to log in —
 * or, with some JWT libraries, signed every token with the literal string
 * "undefined", which is worse than a crash. This runs once, at
 * `ConfigModule.forRoot()`, and throws before Nest finishes bootstrapping
 * if anything critical is missing or malformed, collecting every problem
 * into one error instead of stopping at the first.
 *
 * Deliberately does NOT require `STORAGE_*` or `VAPID_*`: both
 * `StorageService` and `PushService` already have their own intentional
 * "not configured" mode (a `configured: boolean` flag plus a startup
 * warning — uploads/push are simply disabled, nothing crashes). Making
 * those mandatory here would contradict a design that's already correct.
 * What *is* checked is the failure mode a partial config actually causes:
 * one of a pair set without the other silently misbehaves (e.g. an S3
 * access key with no secret) in a way the existing `Boolean(a && b)` guard
 * can't distinguish from "not configured at all" — that half-set case is
 * almost certainly a mistake, not a choice, so it's rejected here.
 */

export interface ValidatedEnv {
  NODE_ENV: "development" | "test" | "production";
  PORT: number;
  DATABASE_URL: string;
  REDIS_URL: string;
  JWT_ACCESS_SECRET: string;
  JWT_ACCESS_EXPIRES_IN: string;
  JWT_REFRESH_EXPIRES_IN: string;
  CORS_ORIGIN: string;
  [key: string]: unknown;
}

const NODE_ENVS = ["development", "test", "production"] as const;
// Same shape auth.service.ts's own parseTtlMs already requires — checked
// here too so a typo'd expiry ("15  m", "15") fails at boot, not at the
// first token issued.
const TTL_PATTERN = /^\d+(?:s|m|h|d)$/;
const MIN_JWT_SECRET_LENGTH = 32;

class EnvValidationError extends Error {
  constructor(problems: string[]) {
    super(
      `Invalid environment configuration — refusing to start:\n` +
        problems.map((p) => `  • ${p}`).join("\n") +
        `\nSee .env.example for the full list of variables.`,
    );
    this.name = "EnvValidationError";
  }
}

function isBlank(value: unknown): boolean {
  return value === undefined || value === null || String(value).trim() === "";
}

function requirePair(
  env: Record<string, unknown>,
  a: string,
  b: string,
  problems: string[],
  label: string,
) {
  const aSet = !isBlank(env[a]);
  const bSet = !isBlank(env[b]);
  if (aSet !== bSet) {
    problems.push(
      `${label}: ${aSet ? a : b} is set but ${aSet ? b : a} is not — set both or neither.`,
    );
  }
}

export function validateEnv(env: Record<string, unknown>): ValidatedEnv {
  const problems: string[] = [];

  const nodeEnv = isBlank(env.NODE_ENV) ? "development" : String(env.NODE_ENV);
  if (!(NODE_ENVS as readonly string[]).includes(nodeEnv)) {
    problems.push(`NODE_ENV must be one of ${NODE_ENVS.join(", ")} (got "${nodeEnv}").`);
  }

  let port = 4000;
  if (!isBlank(env.PORT)) {
    const parsed = Number(env.PORT);
    if (!Number.isInteger(parsed) || parsed < 1 || parsed > 65535) {
      problems.push(`PORT must be an integer between 1 and 65535 (got "${String(env.PORT)}").`);
    } else {
      port = parsed;
    }
  }

  if (isBlank(env.DATABASE_URL)) {
    problems.push("DATABASE_URL is required (Postgres connection string).");
  } else if (!/^postgres(?:ql)?:\/\//.test(String(env.DATABASE_URL))) {
    problems.push('DATABASE_URL must start with "postgres://" or "postgresql://".');
  }

  if (isBlank(env.REDIS_URL)) {
    problems.push("REDIS_URL is required (used by caching, sessions, and BullMQ queues).");
  } else if (!/^rediss?:\/\//.test(String(env.REDIS_URL))) {
    problems.push('REDIS_URL must start with "redis://" or "rediss://".');
  }

  if (isBlank(env.JWT_ACCESS_SECRET)) {
    problems.push(
      "JWT_ACCESS_SECRET is required. A blank secret previously let the server " +
        "boot and sign tokens nobody could verify was safe.",
    );
  } else if (String(env.JWT_ACCESS_SECRET).length < MIN_JWT_SECRET_LENGTH) {
    problems.push(
      `JWT_ACCESS_SECRET must be at least ${MIN_JWT_SECRET_LENGTH} characters ` +
        `(got ${String(env.JWT_ACCESS_SECRET).length}). Generate one with ` +
        `\`node -e "console.log(require('crypto').randomBytes(48).toString('hex'))"\`.`,
    );
  }

  const accessTtl = isBlank(env.JWT_ACCESS_EXPIRES_IN) ? "15m" : String(env.JWT_ACCESS_EXPIRES_IN);
  if (!TTL_PATTERN.test(accessTtl)) {
    problems.push(`JWT_ACCESS_EXPIRES_IN must look like "15m", "1h", "7d" (got "${accessTtl}").`);
  }

  const refreshTtl = isBlank(env.JWT_REFRESH_EXPIRES_IN) ? "30d" : String(env.JWT_REFRESH_EXPIRES_IN);
  if (!TTL_PATTERN.test(refreshTtl)) {
    problems.push(`JWT_REFRESH_EXPIRES_IN must look like "15m", "1h", "7d" (got "${refreshTtl}").`);
  }

  for (const key of ["HYBRID_CONTENT_WEIGHT", "HYBRID_COLLABORATIVE_WEIGHT"]) {
    if (!isBlank(env[key])) {
      const n = Number(env[key]);
      if (Number.isNaN(n) || n < 0 || n > 1) {
        problems.push(`${key} must be a number between 0 and 1 (got "${String(env[key])}").`);
      }
    }
  }

  if (!isBlank(env.TRANSCODE_WORKER_CONCURRENCY)) {
    const n = Number(env.TRANSCODE_WORKER_CONCURRENCY);
    if (!Number.isInteger(n) || n < 1) {
      problems.push(
        `TRANSCODE_WORKER_CONCURRENCY must be a positive integer (got "${String(env.TRANSCODE_WORKER_CONCURRENCY)}").`,
      );
    }
  }

  if (!isBlank(env.WEB_APP_URL)) {
    try {
      new URL(String(env.WEB_APP_URL));
    } catch {
      problems.push(`WEB_APP_URL must be a valid absolute URL (got "${String(env.WEB_APP_URL)}").`);
    }
  }

  // CORS_ORIGIN may be a single origin or a comma-separated list (a
  // staging + prod web app, say) — main.ts splits on the same comma. Each
  // entry must be a real absolute URL, the same bar WEB_APP_URL is held
  // to above, since a typo here doesn't error, it just makes CORS
  // silently reject every request from the browser.
  if (!isBlank(env.CORS_ORIGIN)) {
    const origins = String(env.CORS_ORIGIN).split(",").map((o) => o.trim());
    for (const origin of origins) {
      if (isBlank(origin)) {
        problems.push("CORS_ORIGIN contains an empty entry (check for a stray comma).");
        continue;
      }
      try {
        new URL(origin);
      } catch {
        problems.push(`CORS_ORIGIN entry "${origin}" is not a valid absolute URL.`);
      }
    }
  }

  // See the module comment: half-set pairs are the one failure mode the
  // services' own "configured" flags can't already tell apart from "off".
  requirePair(env, "STORAGE_ACCESS_KEY", "STORAGE_SECRET_KEY", problems, "Object storage");
  requirePair(env, "VAPID_PUBLIC_KEY", "VAPID_PRIVATE_KEY", problems, "Web push");

  if (problems.length > 0) {
    throw new EnvValidationError(problems);
  }

  return {
    ...env,
    NODE_ENV: nodeEnv as ValidatedEnv["NODE_ENV"],
    PORT: port,
    DATABASE_URL: String(env.DATABASE_URL),
    REDIS_URL: String(env.REDIS_URL),
    JWT_ACCESS_SECRET: String(env.JWT_ACCESS_SECRET),
    JWT_ACCESS_EXPIRES_IN: accessTtl,
    JWT_REFRESH_EXPIRES_IN: refreshTtl,
    CORS_ORIGIN: isBlank(env.CORS_ORIGIN) ? "http://localhost:3000" : String(env.CORS_ORIGIN),
  };
}
